import { readFileSync } from 'node:fs';
import { describe, it, expect } from 'vitest';
import { lightNormalizeCode } from '../src/standards/light-normalize.js';
import { splitReplacesParts } from '../src/standards/repository.js';

// Light normalization is THE merge key (user decision 2026-11-23).
// The shared fixture is generated by tests/fixtures/generate-shared.ts
// and is also tested in Reverse_proxy — elib is the source of truth.

interface SharedCase {
  input: string;
  year_field: number | null;
  normalized_code: string | null;
  base_key: string | null;
  code_key_raw: string | null;
  year: number | null;
  amendment_year: number | null;
  is_amendment: boolean | null;
  is_draft: boolean | null;
  needs_review: boolean | null;
  skipped_reason: string | null;
}

const shared = JSON.parse(
  readFileSync(new URL('./fixtures/code-normalize-shared.json', import.meta.url), 'utf8')
) as SharedCase[];

describe('lightNormalizeCode — fixture khóa dùng chung hai repo', () => {
  it(`khớp ${shared.length} case (input + year_field -> khóa)`, () => {
    const mismatches: string[] = [];
    for (const c of shared) {
      const light = lightNormalizeCode(c.input, c.year_field);
      const got = {
        normalized_code: light?.normalized_code ?? null,
        base_key: light?.base_key ?? null,
        code_key_raw: light?.code_key_raw ?? null,
        year: light?.year ?? null,
        amendment_year: light?.amendment_year ?? null,
        is_amendment: light?.is_amendment ?? null,
        is_draft: light?.is_draft ?? null,
        needs_review: light?.needs_review ?? null,
        skipped_reason: light?.skipped_reason ?? null
      };
      const want = {
        normalized_code: c.normalized_code,
        base_key: c.base_key,
        code_key_raw: c.code_key_raw,
        year: c.year,
        amendment_year: c.amendment_year,
        is_amendment: c.is_amendment,
        is_draft: c.is_draft,
        needs_review: c.needs_review,
        skipped_reason: c.skipped_reason
      };
      if (JSON.stringify(got) !== JSON.stringify(want)) {
        mismatches.push(
          `${JSON.stringify(c.input)} (year_field=${c.year_field}): want ${JSON.stringify(want)} got ${JSON.stringify(got)}`
        );
      }
    }
    expect(mismatches).toEqual([]);
  });
});

describe('lightNormalizeCode — quy tắc "/"', () => {
  it('bỏ "/" khi hai bên là chữ cái: ISO/TS = ISO TS, TCVN/ISO = TCVN ISO', () => {
    const withSlash = lightNormalizeCode('TCVN ISO/TS 16949:2011');
    const withSpace = lightNormalizeCode('TCVN ISO TS 16949:2011');
    expect(withSlash?.normalized_code).toBe('TCVNISOTS16949:2011');
    expect(withSlash?.normalized_code).toBe(withSpace?.normalized_code);

    expect(lightNormalizeCode('TCVN ISO TS 9002:2017')?.normalized_code).toBe(
      'TCVNISOTS9002:2017'
    );
    expect(lightNormalizeCode('TCVN/ISO 9001:2015')?.normalized_code).toBe(
      lightNormalizeCode('TCVN ISO 9001:2015')?.normalized_code
    );
    expect(lightNormalizeCode('TCVN/ISO 9001:2015')?.normalized_code).toBe('TCVNISO9001:2015');
  });

  it('giữ "/" khi sau chữ số (hậu tố /BXD, /Amd 1, /AC)', () => {
    expect(lightNormalizeCode('QCVN 02:2016/BXD')?.normalized_code).toBe('QCVN02:2016/BXD');
    const amended = lightNormalizeCode('ISO 9001:2015/Amd 1:2016');
    expect(amended?.normalized_code).toBe('ISO9001:2015/AMD1:2016');
    expect(amended?.is_amendment).toBe(true);
    expect(amended?.year).toBe(2015);
    expect(amended?.base_key).toBe('ISO9001');
    expect(lightNormalizeCode('ISO 9001:2015/AC:2019')?.normalized_code).toBe(
      'ISO9001:2015/AC:2019'
    );
  });

  it('ISO/FDIS là designation riêng, không gộp vào ISO', () => {
    expect(lightNormalizeCode('ISO/FDIS 9001', 2015)?.normalized_code).toBe('ISOFDIS9001:2015');
    expect(lightNormalizeCode('ISO/FDIS 9001', 2015)?.normalized_code).not.toBe(
      lightNormalizeCode('ISO 9001', 2015)?.normalized_code
    );
  });
});

describe('lightNormalizeCode — năm', () => {
  it('cùng tiêu chuẩn từ QT (code không năm + year field) và nguồn viết kèm năm -> cùng khóa', () => {
    const fromQt = lightNormalizeCode('ISO 9001', 2015);
    const yeared = lightNormalizeCode('ISO 9001:2015');
    expect(fromQt?.normalized_code).toBe('ISO9001:2015');
    expect(fromQt?.normalized_code).toBe(yeared?.normalized_code);
    expect(fromQt?.base_key).toBe('ISO9001');
    expect(fromQt?.year).toBe(2015);
    expect(fromQt?.needs_review).toBe(false);
  });

  it('code có ":YYYY" khác trường year -> giữ khóa theo code + needs_review', () => {
    const light = lightNormalizeCode('TCVN 9143:2022', 2020);
    expect(light?.normalized_code).toBe('TCVN9143:2022');
    expect(light?.year).toBe(2022);
    expect(light?.needs_review).toBe(true);
  });

  it('năm hai chữ số giữ nguyên, không suy ra 1988', () => {
    const light = lightNormalizeCode('14 TCN 58-88');
    expect(light?.normalized_code).toBe('14TCN58-88');
    expect(light?.year).toBeNull();
    expect(light?.base_key).toBe('14TCN58-88');
  });

  it('mã không năm + không year field -> khóa không năm (normativeReference)', () => {
    const light = lightNormalizeCode('TCVN 4253');
    expect(light?.normalized_code).toBe('TCVN4253');
    expect(light?.base_key).toBe('TCVN4253');
    expect(light?.year).toBeNull();
  });

  it('amendment không có ":năm" + có year field -> không thêm ":year", needs_review', () => {
    const light = lightNormalizeCode('ISO 9001/Amd 1', 2016);
    expect(light?.normalized_code).toBe('ISO9001/AMD1');
    expect(light?.is_amendment).toBe(true);
    expect(light?.needs_review).toBe(true);
    expect(light?.year).toBe(2016);
  });

  it('is_amendment qua regex /AMD /COR /AC +A\\d', () => {
    expect(lightNormalizeCode('EN 1994-1-1:2004/Amd 1:2010')?.is_amendment).toBe(true);
    expect(lightNormalizeCode('ISO 9001:2015/Cor 1:2019')?.is_amendment).toBe(true);
    expect(lightNormalizeCode('EN 1090-2:2018+A1:2020')?.is_amendment).toBe(true);
    expect(lightNormalizeCode('TCVN 9143:2022')?.is_amendment).toBe(false);
  });
});

describe('lightNormalizeCode — mã rác / không chuẩn hóa được', () => {
  it('rỗng, khoảng trắng, ký tự lạ, chỉ chữ cái (không có số) -> null', () => {
    expect(lightNormalizeCode('')).toBeNull();
    expect(lightNormalizeCode('   ')).toBeNull();
    expect(lightNormalizeCode('???')).toBeNull();
    // Quy tắc đã chốt trong code: mã tiêu chuẩn luôn có số; chuỗi chỉ
    // gồm chữ cái không phải mã.
    expect(lightNormalizeCode('abc')).toBeNull();
    expect(lightNormalizeCode('TCVN')).toBeNull();
  });

  it('bỏ dấu tiếng Việt + viết hoa + bỏ khoảng trắng/xuống dòng', () => {
    expect(lightNormalizeCode('TCĐBVN 01:2020')?.normalized_code).toBe('TCDBVN01:2020');
    expect(lightNormalizeCode('tcvn 9143:2022')?.normalized_code).toBe('TCVN9143:2022');
    expect(lightNormalizeCode('TCVN\n9143:2022')?.normalized_code).toBe('TCVN9143:2022');
  });
});

describe('lightNormalizeCode — luật năm gạch ngang (bổ sung 2026-11-23)', () => {
  it('-YYYY trùng trường year -> :YYYY, hết năm đôi', () => {
    expect(lightNormalizeCode('GB/T 19001-2016', 2016)?.normalized_code).toBe('GBT19001:2016');
    expect(lightNormalizeCode('TCVN 9143-2022', 2022)?.normalized_code).toBe('TCVN9143:2022');
    expect(lightNormalizeCode('EN 50122-1-2011', 2011)?.normalized_code).toBe('EN50122-1:2011');
    const light = lightNormalizeCode('GB/T 19001-2016', 2016);
    expect(light?.year).toBe(2016);
    expect(light?.base_key).toBe('GBT19001');
    expect(light?.needs_review).toBe(false);
  });

  it('/YYYY trùng trường year -> :YYYY', () => {
    expect(lightNormalizeCode('EN 50172/2004', 2004)?.normalized_code).toBe('EN50172:2004');
    expect(lightNormalizeCode('EN 1337-1/2011', 2011)?.normalized_code).toBe('EN1337-1:2011');
  });

  it('-YYYY-MM -> :YYYY, tháng bị bỏ khỏi khóa', () => {
    const light = lightNormalizeCode('ISO 9001-2015-09', 2015);
    expect(light?.normalized_code).toBe('ISO9001:2015');
    expect(light?.year).toBe(2015);
    expect(lightNormalizeCode('IEC 60850/2007-02', 2007)?.normalized_code).toBe('IEC60850:2007');
  });

  it('-YY chỉ khi khớp hai chữ số cuối của trường year -> :YYYY đủ', () => {
    expect(lightNormalizeCode('ASTM D 4719-07', 2007)?.normalized_code).toBe('ASTMD4719:2007');
    expect(lightNormalizeCode('AASHTO T27-99', 1999)?.normalized_code).toBe('AASHTOT27:1999');
    expect(lightNormalizeCode('GBJ 22-87', 1987)?.normalized_code).toBe('GBJ22:1987');
  });

  it('-YY không khớp -> giữ nguyên, nối :year như cũ', () => {
    expect(lightNormalizeCode('ASTM D 4719-07', 2010)?.normalized_code).toBe('ASTMD4719-07:2010');
  });

  it('-YY sau một "-" khác là phần/chương, không phải năm (EN 1993-1-10)', () => {
    expect(lightNormalizeCode('EN 1993-1-10', 2010)?.normalized_code).toBe('EN1993-1-10:2010');
  });

  it('-YYYY không khớp trường year -> giữ nguyên + nối :year + needs_review', () => {
    const light = lightNormalizeCode('TCVN 9143-2020', 2022);
    expect(light?.normalized_code).toBe('TCVN9143-2020:2022');
    expect(light?.year).toBe(2022);
    expect(light?.needs_review).toBe(true);
  });

  it('không có trường year -> năm gạch ngang giữ nguyên (14 TCN 58-88)', () => {
    expect(lightNormalizeCode('14 TCN 58-88')?.normalized_code).toBe('14TCN58-88');
    expect(lightNormalizeCode('TCVN 9143-2022')?.normalized_code).toBe('TCVN9143-2022');
    expect(lightNormalizeCode('TCVN 9143-2022')?.year).toBeNull();
  });
});

describe('lightNormalizeCode — phân cách nhóm số + needs_review (bổ sung)', () => {
  it('khoảng trắng giữa hai nhóm số -> giữ "-" + needs_review', () => {
    const light = lightNormalizeCode('TCVN 1234 12');
    expect(light?.normalized_code).toBe('TCVN1234-12');
    expect(light?.needs_review).toBe(true);
    expect(lightNormalizeCode('TCVN 1234 1231')?.normalized_code).toBe('TCVN1234-1231');
    expect(lightNormalizeCode('TCVN 1234 1231')?.needs_review).toBe(true);
  });

  it('mã thường không bị ảnh hưởng', () => {
    const light = lightNormalizeCode('TCVN 9143:2022');
    expect(light?.normalized_code).toBe('TCVN9143:2022');
    expect(light?.needs_review).toBe(false);
    // "TCVN 1234-1 2013": nhóm số cuối trùng đúng trường year -> coi
    // là năm (":2013"), KHÔNG needs_review (vòng sửa cuối 2).
    const grouped = lightNormalizeCode('TCVN 1234-1 2013', 2013);
    expect(grouped?.normalized_code).toBe('TCVN1234-1:2013');
    expect(grouped?.year).toBe(2013);
    expect(grouped?.needs_review).toBe(false);
  });
});

describe('lightNormalizeCode — needs_review năm ngoài khoảng + tổ chức lặp đôi', () => {
  it('năm ngoài [1900, năm hiện tại + 1] -> needs_review, khóa vẫn dựng', () => {
    expect(lightNormalizeCode('ISO 231123-1:1231')?.needs_review).toBe(true);
    expect(lightNormalizeCode('ISO 231123-1:1231')?.normalized_code).toBe('ISO231123-1:1231');
    expect(lightNormalizeCode('TCVN 9143:1800')?.needs_review).toBe(true);
    expect(lightNormalizeCode('TCVN 9143:2999')?.needs_review).toBe(true);
    expect(lightNormalizeCode('ISO 9001', 1800)?.needs_review).toBe(true);
    expect(lightNormalizeCode('TCVN 9143:2022')?.needs_review).toBe(false);
  });

  it('tổ chức lặp đôi (ENEN / EN EN) -> needs_review, giữ nguyên dạng lặp', () => {
    const doubled = lightNormalizeCode('ENEN 1234:2020', 2020);
    expect(doubled?.normalized_code).toBe('ENEN1234:2020');
    expect(doubled?.needs_review).toBe(true);
    expect(lightNormalizeCode('EN EN 1234:2020', 2020)?.needs_review).toBe(true);
    expect(lightNormalizeCode('EN EN 1090')?.needs_review).toBe(true);
    // Tổ chức thường không bị gắn cờ:
    expect(lightNormalizeCode('EN ISO 9001:2015')?.needs_review).toBe(false);
    expect(lightNormalizeCode('TCVN ISO 9001:2015')?.needs_review).toBe(false);
    expect(lightNormalizeCode('IEEE 802.3:2022')?.needs_review).toBe(false);
  });
});

describe('lightNormalizeCode — bỏ qua mã không có hai chữ cái trước phần số', () => {
  it('chỉ có số / ICS / một chữ cái -> null', () => {
    expect(lightNormalizeCode('12345')).toBeNull();
    expect(lightNormalizeCode('93.160')).toBeNull();
    expect(lightNormalizeCode('T 27')).toBeNull();
  });

  it('"14 TCN 58-88" vẫn hợp lệ (TCN đứng trước 58)', () => {
    expect(lightNormalizeCode('14 TCN 58-88')?.normalized_code).toBe('14TCN58-88');
    expect(lightNormalizeCode('TCVN 4253')?.normalized_code).toBe('TCVN4253');
  });
});

describe('lightNormalizeCode — base_key/year từ ":năm" ĐẦU TIÊN', () => {
  it('EN 1994-1-1:2004+A1:2010 -> base EN1994-1-1, year 2004 (bản chính)', () => {
    const light = lightNormalizeCode('EN 1994-1-1:2004+A1:2010', 2004);
    expect(light?.normalized_code).toBe('EN1994-1-1:2004+A1:2010');
    expect(light?.base_key).toBe('EN1994-1-1');
    expect(light?.year).toBe(2004);
    expect(light?.is_amendment).toBe(true);
    expect(light?.needs_review).toBe(false);
  });

  it('trường year so với năm ĐẦU TIÊN khi xét lệch', () => {
    expect(lightNormalizeCode('EN 1994-1-1:2004+A1:2010', 2010)?.needs_review).toBe(true);
    // Mã thường giữ nguyên hành vi cũ:
    const plain = lightNormalizeCode('ISO 9001:2015/Amd 1:2016', 2015);
    expect(plain?.base_key).toBe('ISO9001');
    expect(plain?.year).toBe(2015);
    expect(plain?.needs_review).toBe(false);
  });
});

describe('lightNormalizeCode — -YY chỉ cho allowlist tổ chức năm 2 chữ số (vòng sửa cuối)', () => {
  it('QT-style: số phần 2 chữ số trùng 2 số cuối của year KHÔNG bị nuốt thành năm', () => {
    const light = lightNormalizeCode('ISO 1234-13', 2013);
    expect(light?.normalized_code).toBe('ISO1234-13:2013');
    expect(light?.normalized_code).not.toBe('ISO1234:2013');
    expect(light?.year).toBe(2013);
    expect(light?.base_key).toBe('ISO1234-13');
    expect(light?.needs_review).toBe(true);
  });

  it('allowlist vẫn đổi: ASTM, AASHTO, GBJ, GB, TCN cũ', () => {
    expect(lightNormalizeCode('ASTM D 4719-07', 2007)?.normalized_code).toBe('ASTMD4719:2007');
    expect(lightNormalizeCode('AASHTO T27-99', 1999)?.normalized_code).toBe('AASHTOT27:1999');
    expect(lightNormalizeCode('GBJ 22-87', 1987)?.normalized_code).toBe('GBJ22:1987');
    expect(lightNormalizeCode('GB 50157-03', 2003)?.normalized_code).toBe('GB50157:2003');
    expect(lightNormalizeCode('14 TCN 58-88', 1988)?.normalized_code).toBe('14TCN58:1988');
    expect(lightNormalizeCode('ASTM C172-04', 2004)?.normalized_code).toBe('ASTMC172:2004');
  });

  it('ngoài allowlist: giữ -YY + nối :year + needs_review; EN 1993-1-10 không đổi', () => {
    const en = lightNormalizeCode('EN 1993-1-10', 2010);
    expect(en?.normalized_code).toBe('EN1993-1-10:2010');
    const tcvn = lightNormalizeCode('TCVN 1234-13', 2013);
    expect(tcvn?.normalized_code).toBe('TCVN1234-13:2013');
    expect(tcvn?.needs_review).toBe(true);
  });
});

describe('lightNormalizeCode — cắt từ "(" + văn xuôi catalog (vòng sửa cuối)', () => {
  it('cắt ngoặc: khóa sạch, parenthetical giữ riêng, hết năm đôi', () => {
    const light = lightNormalizeCode('TCVN 13566:2022 (các phần 1-6)', 2022);
    expect(light?.normalized_code).toBe('TCVN13566:2022');
    expect(light?.parenthetical).toBe('các phần 1-6');
    // Ngoặc chứa chữ chỉ phần -> needs_review (vòng sửa cuối 2):
    // thông tin phần bị cắt khỏi khóa nên phải có người rà soát.
    expect(light?.needs_review).toBe(true);

    const equiv = lightNormalizeCode('TCVN 9386-1:2012 (ISO 3010:2001)', 2012);
    expect(equiv?.normalized_code).toBe('TCVN9386-1:2012');
    expect(equiv?.parenthetical).toBe('ISO 3010:2001');
    expect(lightNormalizeCode(equiv?.parenthetical ?? '')?.normalized_code).toBe(
      'ISO3010:2001'
    );

    // Ngoặc không đóng vẫn cắt được:
    const unclosed = lightNormalizeCode('TCVN 13695-1:2023 (BS EN 13146-1:2019', 2023);
    expect(unclosed?.normalized_code).toBe('TCVN13695-1:2023');
    expect(unclosed?.parenthetical).toBe('BS EN 13146-1:2019');
  });

  it('ngoặc ngày "(YYYY-MM)" cấp năm khi không có trường year', () => {
    const light = lightNormalizeCode('ISO 9001 (2008-11)');
    expect(light?.normalized_code).toBe('ISO9001:2008');
    expect(light?.year).toBe(2008);
  });

  it('văn xuôi (đến / các phần / dấu phẩy) -> không tạo khóa, needs_review, skipped_reason', () => {
    const range = lightNormalizeCode('BS EN 13146-1 đến 10:2019', 2019);
    expect(range).not.toBeNull();
    expect(range?.normalized_code).toBeNull();
    expect(range?.needs_review).toBe(true);
    expect(range?.skipped_reason).toBe('catalog-prose');

    const comma = lightNormalizeCode('TCVN 13566-1,2,3,4,5:2022', 2022);
    expect(comma?.normalized_code).toBeNull();
    expect(comma?.skipped_reason).toBe('catalog-prose');

    const va = lightNormalizeCode('TCVN 13566-1, 2, 3, 4 và 5:2022', 2022);
    expect(va?.normalized_code).toBeNull();

    // Mã thật không bị gắn nhầm:
    expect(lightNormalizeCode('TCVN 9143:2022')?.skipped_reason).toBeNull();
    expect(lightNormalizeCode('EN 50129')?.normalized_code).toBe('EN50129');
  });

  it('khóa phải khớp [A-Z0-9.\\-:/+_]', () => {
    const light = lightNormalizeCode('TCVN 9143:2022');
    expect(/^[A-Z0-9.\-:\/+_]+$/.test(light?.normalized_code ?? '')).toBe(true);
  });
});

describe('lightNormalizeCode — amendment đứng một mình + is_draft + IEEE Std (vòng sửa cuối)', () => {
  it('ISO 231123-1/AC:2009 -> base ISO231123-1, year null, amendment_year 2009', () => {
    const light = lightNormalizeCode('ISO 231123-1/AC:2009');
    expect(light?.normalized_code).toBe('ISO231123-1/AC:2009');
    expect(light?.base_key).toBe('ISO231123-1');
    expect(light?.year).toBeNull();
    expect(light?.amendment_year).toBe(2009);
    expect(light?.is_amendment).toBe(true);
  });

  it('amendment sau năm chính: year = năm chính, amendment_year riêng', () => {
    const light = lightNormalizeCode('ISO 9001:2015/Amd 1:2016', 2015);
    expect(light?.year).toBe(2015);
    expect(light?.amendment_year).toBe(2016);
    expect(light?.base_key).toBe('ISO9001');
    const plus = lightNormalizeCode('EN 1994-1-1:2004+A1:2010', 2004);
    expect(plus?.year).toBe(2004);
    expect(plus?.amendment_year).toBe(2010);
  });

  it('is_draft: FDIS/DIS/PRF/prEN/FprEN', () => {
    expect(lightNormalizeCode('ISO/FDIS 9001', 2015)?.is_draft).toBe(true);
    expect(lightNormalizeCode('ISO/DIS 9001', 2015)?.is_draft).toBe(true);
    expect(lightNormalizeCode('prEN 1090-2:2018')?.is_draft).toBe(true);
    expect(lightNormalizeCode('FprEN 1090-2:2018')?.is_draft).toBe(true);
    expect(lightNormalizeCode('ISO 9001:2015')?.is_draft).toBe(false);
    expect(lightNormalizeCode('TCVN 9143:2022')?.is_draft).toBe(false);
  });

  it('bỏ "STD" sau IEEE', () => {
    expect(lightNormalizeCode('IEEE Std 802.11:2020', 2020)?.normalized_code).toBe(
      'IEEE802.11:2020'
    );
    expect(lightNormalizeCode('IEEE Std 802.11')?.normalized_code).toBe('IEEE802.11');
    expect(lightNormalizeCode('IEEE 802.3:2022')?.normalized_code).toBe('IEEE802.3:2022');
  });
});

describe('splitReplacesParts — replaces của TCVN_QT (mẫu ISO 9001 thật)', () => {
  it('tách "*", lấy năm từ "(YYYY-MM)", corrigendum văn xuôi đánh dấu rawOnly', () => {
    const parts = splitReplacesParts(
      'ISO 9001 (2008-11)*ISO/FDIS 9001 (2015-07)*ISO 9001 Technical Corrigendum 1 (2009-07)'
    );
    expect(parts).toEqual([
      { code: 'ISO 9001', year: 2008, raw: 'ISO 9001 (2008-11)', rawOnly: false },
      { code: 'ISO/FDIS 9001', year: 2015, raw: 'ISO/FDIS 9001 (2015-07)', rawOnly: false },
      {
        code: 'ISO 9001 Technical Corrigendum 1',
        year: 2009,
        raw: 'ISO 9001 Technical Corrigendum 1 (2009-07)',
        rawOnly: true
      }
    ]);
    // Khóa đích tương ứng:
    expect(lightNormalizeCode(parts[0].code, parts[0].year)?.normalized_code).toBe('ISO9001:2008');
    expect(lightNormalizeCode(parts[1].code, parts[1].year)?.normalized_code).toBe(
      'ISOFDIS9001:2015'
    );
  });
});

describe('lightNormalizeCode — tự từ chối multi-code / prose (vòng sửa cuối 2)', () => {
  it('chuỗi chứa "*" -> skipped_reason=multi-code, không tạo khóa', () => {
    const light = lightNormalizeCode(
      'ISO 9001 (2008-11)*ISO/FDIS 9001 (2015-07)*ISO 9001 Technical Corrigendum 1 (2009-07)'
    );
    expect(light).not.toBeNull();
    expect(light?.normalized_code).toBeNull();
    expect(light?.base_key).toBeNull();
    expect(light?.code_key_raw).toBeNull();
    expect(light?.skipped_reason).toBe('multi-code');
  });

  it('từ đầy đủ CORRIGENDUM/AMENDMENT/TECHNICAL -> skipped_reason=prose', () => {
    const corr = lightNormalizeCode('ISO 9001 Technical Corrigendum 1 (2009-07)');
    expect(corr?.normalized_code).toBeNull();
    expect(corr?.skipped_reason).toBe('prose');
    expect(lightNormalizeCode('ISO 9001 Amendment 1:2016')?.skipped_reason).toBe('prose');
    expect(lightNormalizeCode('iso 9001 corrigendum 1')?.skipped_reason).toBe('prose');
  });

  it('dạng viết tắt /Amd /Cor không bị từ chối', () => {
    expect(lightNormalizeCode('ISO 9001:2015/Amd 1:2016')?.normalized_code).toBe(
      'ISO9001:2015/AMD1:2016'
    );
    expect(lightNormalizeCode('ISO 9001:2015/Cor 1:2019')?.skipped_reason).toBeNull();
    expect(lightNormalizeCode('TCVN 9143:2022')?.skipped_reason).toBeNull();
  });
});

describe('lightNormalizeCode — code_key_raw (khóa trước khi viết lại năm)', () => {
  it('"14 TCN 58-88" + 1988: normalized 14TCN58:1988, code_key_raw giữ -88', () => {
    const light = lightNormalizeCode('14 TCN 58-88', 1988);
    expect(light?.normalized_code).toBe('14TCN58:1988');
    expect(light?.code_key_raw).toBe('14TCN58-88');
    expect(light?.base_key).toBe('14TCN58');
    expect(light?.year).toBe(1988);
  });

  it('code không năm + trường year: code_key_raw là dạng chưa nối ":year"', () => {
    const light = lightNormalizeCode('ISO 9001', 2015);
    expect(light?.normalized_code).toBe('ISO9001:2015');
    expect(light?.code_key_raw).toBe('ISO9001');
  });

  it('năm gạch ngang: code_key_raw giữ dạng gạch, normalized đổi sang ":YYYY"', () => {
    const light = lightNormalizeCode('GB/T 19001-2016', 2016);
    expect(light?.normalized_code).toBe('GBT19001:2016');
    expect(light?.code_key_raw).toBe('GBT19001-2016');
  });

  it('code đã có ":YYYY": code_key_raw = normalized_code', () => {
    const light = lightNormalizeCode('TCVN 9143:2022');
    expect(light?.code_key_raw).toBe('TCVN9143:2022');
    expect(light?.code_key_raw).toBe(light?.normalized_code);
  });

  it('mã bị bỏ qua -> code_key_raw null', () => {
    expect(lightNormalizeCode('ISO 9001*ISO 9002')?.code_key_raw).toBeNull();
    expect(lightNormalizeCode('BS EN 13146-1 đến 10:2019')?.code_key_raw).toBeNull();
  });
});

describe('lightNormalizeCode — ngoặc chứa chữ phần/khoảng -> needs_review (vòng sửa cuối 2)', () => {
  it('"các phần" / "phần ... đến" / "từ ... đến" trong ngoặc bị cắt -> needs_review', () => {
    expect(
      lightNormalizeCode('TCVN 13566:2022 (các phần 1-6)', 2022)?.needs_review
    ).toBe(true);
    expect(
      lightNormalizeCode('TCVN 1234:2020 (phần 1 đến 3)', 2020)?.needs_review
    ).toBe(true);
    expect(
      lightNormalizeCode('TCVN 1234:2020 (từ 1 đến 10, 2019)', 2020)?.needs_review
    ).toBe(true);
    // Không dấu cũng bắt được:
    expect(
      lightNormalizeCode('TCVN 13566:2022 (cac phan 1-6)', 2022)?.needs_review
    ).toBe(true);
  });

  it('ngoặc mã tương đương / ngoặc ngày không bị gắn cờ', () => {
    expect(
      lightNormalizeCode('TCVN 9386-1:2012 (ISO 3010:2001)', 2012)?.needs_review
    ).toBe(false);
    expect(lightNormalizeCode('ISO 9001 (2008-11)')?.needs_review).toBe(false);
    expect(lightNormalizeCode('TCVN 9143:2022')?.needs_review).toBe(false);
  });
});

describe('lightNormalizeCode — nhóm số cuối trùng trường year (vòng sửa cuối 2)', () => {
  it('"TCVN 1234-1 2013" + 2013 -> :2013, không needs_review', () => {
    const light = lightNormalizeCode('TCVN 1234-1 2013', 2013);
    expect(light?.normalized_code).toBe('TCVN1234-1:2013');
    expect(light?.code_key_raw).toBe('TCVN1234-1-2013');
    expect(light?.needs_review).toBe(false);
  });

  it('nhóm số cuối 4 chữ số nhưng khác trường year -> vẫn needs_review', () => {
    const light = lightNormalizeCode('TCVN 1234 2013', 2020);
    expect(light?.normalized_code).toBe('TCVN1234-2013:2020');
    expect(light?.needs_review).toBe(true);
  });

  it('nhóm số không phải năm -> vẫn giữ "-" + needs_review như cũ', () => {
    const light = lightNormalizeCode('TCVN 1234 12', 2020);
    expect(light?.normalized_code).toBe('TCVN1234-12:2020');
    expect(light?.needs_review).toBe(true);
  });
});

describe('lightNormalizeCode — mã bổ sung bảng (vòng sửa cuối 2)', () => {
  it('"ISO 1234-13" + 2013: giữ -13, nối :2013, needs_review', () => {
    const light = lightNormalizeCode('ISO 1234-13', 2013);
    expect(light?.normalized_code).toBe('ISO1234-13:2013');
    expect(light?.code_key_raw).toBe('ISO1234-13');
    expect(light?.year).toBe(2013);
    expect(light?.needs_review).toBe(true);
  });

  it('"JIS B8009-12" + 2012: JIS ngoài allowlist -YY -> giữ -12, nối :2012, needs_review', () => {
    const light = lightNormalizeCode('JIS B8009-12', 2012);
    expect(light?.normalized_code).toBe('JISB8009-12:2012');
    expect(light?.normalized_code).not.toBe('JISB8009:2012');
    expect(light?.code_key_raw).toBe('JISB8009-12');
    expect(light?.year).toBe(2012);
    expect(light?.needs_review).toBe(true);
  });
});
